svg.script:
(function() {
  var root = document.getElementById('a12p18h-root');
  var titleElem = document.getElementById('a12p18h-readout-title');
  var descElem = document.getElementById('a12p18h-readout-desc');
  var clinElem = document.getElementById('a12p18h-readout-clinical');
  var dotElem = document.getElementById('a12p18h-card-dot');

  var dataMap = {
    'all': {
      title: 'CONVERSÃO DE PLANO: A LÓGICA DAS DUAS PERSPECTIVAS',
      desc: 'De perfil (corte sagital), o assoalho é uma pilha de camadas viscerais e musculares. Ao mudar o observador para baixo, essa mesma saída pélvica projeta-se em dois territórios de superfície: os Trígonos Urogenital e Anal.',
      clin: '• A Linha Bituberosa (unindo as tuberosidades isquiáticas) é o divisor transversal que delimita os dois trígonos no corpo perineal.',
      dotColor: 'var(--a12p18h-accent-ug, #ff3377)'
    },
    'ug': {
      title: 'TRÍGONO UROGENITAL (REGIÃO ANTERIOR)',
      desc: 'Delimitado pela sínfise púbica (ápice anterior), ramos isquiopúbicos (laterais) e linha bituberosa (base posterior). É atravessado pela uretra e pela vagina. Em ortostatismo, apresenta orientação quase horizontal.',
      clin: '• Contém a membrana do períneo e a musculatura erétil/superficial. Fixa-se fortemente ao corpo perineal em sua margem posterior.',
      dotColor: 'var(--a12p18h-accent-ug, #ff3377)'
    },
    'anal': {
      title: 'TRÍGONO ANAL (REGIÃO POSTERIOR)',
      desc: 'Delimitado pela linha bituberosa (base anterior), ligamentos sacrotuberóides/tuberosidades (laterais) e cóccix (ápice posterior). Contém o orifício anal, o ligamento anococcígeo e o gorduroso espaço da fossa isquioanal.',
      clin: '• Inclina-se dorsossuperiormente. Diferente do trígono UG, não possui membrana fibrosa contínua, permitindo expansão durante a defecação.',
      dotColor: 'var(--a12p18h-accent-anal, #ba68c8)'
    },
    'bitub': {
      title: 'LINHA BITUBEROSA & CORPO PERINEAL',
      desc: 'Linha transversal imaginária que conecta os dois tubérculos isquiáticos. Passa exatamente pelo Corpo Perineal (centro tendíneo do períneo), nódulo fibromuscular onde convergem os esfíncteres e músculos perineais.',
      clin: '• É o eixo de dobradiça da conversão de plano: o ponto de encontro anatômico entre o Trígono Urogenital e o Trígono Anal.',
      dotColor: 'var(--a12p18h-line-bitub, #ffea00)'
    },
    'pubis': {
      title: 'PONTO FIXO ANTERIOR: SÍNFISE PÚBICA',
      desc: 'Articulação cartilaginosa anterior. No corte sagital, é o limite anterior da bacia. Na vista inferior, forma o ápice do Trígono Urogenital e o ponto de origem do arco púbico.',
      clin: '• Referência óssea palpável anterior para medição e delimitação do diâmetro sagital da saída pélvica.',
      dotColor: 'var(--a12p18h-bone, #e3b0c4)'
    },
    'coccyx': {
      title: 'PONTO FIXO POSTERIOR: CÓCCIX',
      desc: 'Vértice ósseo posterior da saída pélvica. No corte sagital, encerra a curva sacrococcígea. Na vista inferior, constitui o ápice posterior do Trígono Anal.',
      clin: '• Serve de inserção para o músculo levantador do ânus e para o ligamento anococcígeo.',
      dotColor: 'var(--a12p18h-accent-anal, #ba68c8)'
    },
    'tuberosity': {
      title: 'VÉRTICES LATERAIS: TUBEROSIDADES ISQUIÁTICAS',
      desc: 'Prominências ósseas isquiáticas laterais (direita e esquerda). Suportam o peso do corpo na posição sentada e ancoram as extremidades da Linha Bituberosa.',
      clin: '• Definem o diâmetro bituberoso (transverso) da saída pélvica, fundamental na avaliação tocoginecológica.',
      dotColor: 'var(--a12p18h-bone, #e3b0c4)'
    }
  };

  window.a12p18hSetScene = function(sceneKey) {
    root.setAttribute('data-scene', sceneKey);
    var data = dataMap[sceneKey] || dataMap['all'];
    if (titleElem) titleElem.textContent = data.title;
    if (descElem) descElem.textContent = data.desc;
    if (clinElem) clinElem.textContent = data.clin;
    if (dotElem) dotElem.style.fill = data.dotColor;

    // Clear active spot highlights
    var spots = root.querySelectorAll('.a12p18h-spot-active');
    for (var i = 0; i < spots.length; i++) {
      spots[i].classList.remove('a12p18h-spot-active');
    }
  };

  window.a12p18hSelectSpot = function(spotKey) {
    var data = dataMap[spotKey];
    if (!data) return;

    root.setAttribute('data-active-spot', spotKey);
    if (titleElem) titleElem.textContent = data.title;
    if (descElem) descElem.textContent = data.desc;
    if (clinElem) clinElem.textContent = data.clin;
    if (dotElem) dotElem.style.fill = data.dotColor;

    // Synchronized highlight in both views
    var spots = root.querySelectorAll('.a12p18h-spot-active');
    for (var i = 0; i < spots.length; i++) {
      spots[i].classList.remove('a12p18h-spot-active');
    }

    var targets = root.querySelectorAll('[data-spot="' + spotKey + '"]');
    for (var j = 0; j < targets.length; j++) {
      targets[j].classList.add('a12p18h-spot-active');
    }
  };

  window.a12p18hKeyScene = function(evt, sceneKey) {
    if (evt.key === 'Enter' || evt.key === ' ') {
      evt.preventDefault();
      a12p18hSetScene(sceneKey);
    }
  };

  window.a12p18hKeySpot = function(evt, spotKey) {
    if (evt.key === 'Enter' || evt.key === ' ') {
      evt.preventDefault();
      a12p18hSelectSpot(spotKey);
    }
  };
})();
